import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.8tqBsFWt.js";const p=JSON.parse('{"title":"Command by Intent","description":"","frontmatter":{"title":"Command by Intent","order":6},"headers":[],"relativePath":"about/chapters/06-command-by-intent.md","filePath":"about/chapters/06-command-by-intent.md"}'),i={name:"about/chapters/06-command-by-intent.md"};function r(s,e,l,d,h,m){return a(),o("div",null,[...e[0]||(e[0]=[n('<h3 id="_06-command-by-intent" tabindex="-1">06.<br>Command by Intent <a class="header-anchor" href="#_06-command-by-intent" aria-label="Permalink to &quot;06.&lt;br&gt;Command by Intent&quot;">​</a></h3><h4 id="golden-rules-to-live-by" tabindex="-1">Golden Rules to Live By <a class="header-anchor" href="#golden-rules-to-live-by" aria-label="Permalink to &quot;Golden Rules to Live By&quot;">​</a></h4><blockquote><p>Command By Intent is a clear, concise statement of an operation&#39;s purpose and desired end state, enabling subordinates to exercise initiative and act independently to achieve goals, even if the original plan fails</p></blockquote><p>Life is made so much simpler by using this military doctrine (from the book <em>Extreme Ownership</em>) in agency operations, and almost no-one uses it because it requires trust in the people you hired. Despite the exhaustive, hire-wire job descriptions you send it out into the world, trust is rare in agencies, mostly because &#39;failure&#39; is forbidden. By defining golden rules and empowering your people to improvise, you liberate both parties. There will be mistakes. You will need to have adult conversations, give feedback, and criticize (each other). But the net result is true delegation that:</p><ol><li>Helps you face reality</li><li>Separates what you, as an owner, <em>do</em> and <em>own</em></li><li>Defines your operating values</li><li>Enables the Talent Siphon</li></ol><p>Put differently, you want a team that doesn&#39;t sit waiting to be told what to do. You want a team that learns and improves by learning <em>how to think</em>.</p><p>There are no commandments set in stone, but there are personal golden rules you demand of your people. Examples might look like:</p><ul><li>Projects end on time</li><li>No free work as concessions</li><li>No work happens out-of-hours unless in extreme need</li></ul><p>Another agencies&#39; golden rules might differ considerably:</p><ul><li>Clients get a reply inside 10 minutes in working hours</li><li>Always present to clients in person</li><li>Always prefer quality over deadlines. If we can make it better, but deliver late, we will</li></ul><p>This level of trust enables personal and professional development, creating a high-functioning team, faster and more effectively than hiring &#39;the best people&#39; you can find.</p><h4 id="most-likely-to-be-misunderstood" tabindex="-1">Most Likely to Be Misunderstood <a class="header-anchor" href="#most-likely-to-be-misunderstood" aria-label="Permalink to &quot;Most Likely to Be Misunderstood&quot;">​</a></h4><p>There is one role in most companies your size which is grossly misunderstood: the role of project manager. For some reason, project managers are often treated as domestic labor. My guess is this happened due to the broad skillset required and the abundance of more affordable female labor. This disrespect usually manifests as an owner-operator asking their project manager: &quot;Please send that email to the client.&quot; The person in charge usually treats project managers as note takers, calendar-setters, and the people responsible for catching client curveballs. They&#39;re usually not in the top half of earners, women, and overlooked. That&#39;s about to change.</p><p>You&#39;re about to put the word &quot;manager&quot; into &quot;project manager.&quot;</p><h5 id="paraphrasing" tabindex="-1">Paraphrasing <a class="header-anchor" href="#paraphrasing" aria-label="Permalink to &quot;Paraphrasing&quot;">​</a></h5><p>It&#39;s hard to overstate how important it is that your project manager can paraphrase what someone just said. The short answer is that it&#39;s at least as important for people to be understood as it is for them to be able to express themselves. Employees lose confidence in their role, their management, or their company because they have no meaningful stake in the relationship or the environment. Everyone on your team should be able to paraphrase, but it&#39;s especially important for a role where communication, understanding, and a cool head are as important as they are for a project manager. Angry people make bad decisions. It is not your project manager&#39;s job to play mother or therapist to anyone on your team (you included). The way you avoid project managers catching everyone&#39;s problems is by insisting on their ability to build relationships with internal and external stakeholders, and nothing makes people heard and understood quicker or better than someone making eye contact, staying quiet, and then, at the opportune time, summarizing what they heard concisely. If that sounds like an oversimplification, it&#39;s because you&#39;re underthinking it.</p>',16)])])}const c=t(i,[["render",r]]);export{p as __pageData,c as default};
